-- Generated by `pnpm --filter @carbon/database authz migration` from packages/database/src/authz. Do not edit.

-- Ships these rules to databases where `authz sync` does not run after migrations yet.

CREATE OR REPLACE FUNCTION public.check_workflow_owner_change(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller text;
BEGIN
  -- A workflow runs with its owner's permissions, so an API role may only own
  -- what it creates and never move it to someone else. Reads the request role,
  -- as check_employee_type_change does.
  IF current_setting('role', true) IN ('anon', 'authenticated') IS NOT TRUE THEN
    RETURN;
  END IF;

  IF p_operation = 'UPDATE'
     AND (p_new->>'ownerId') IS DISTINCT FROM (p_old->>'ownerId') THEN
    RAISE EXCEPTION 'A workflow''s owner cannot be changed'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Publishing picks what runs as the owner, so only the owner may point it at a
  -- version; clearing it (unpublish) stays open.
  IF p_operation = 'UPDATE'
     AND (p_new->>'publishedVersionId') IS NOT NULL
     AND (p_new->>'publishedVersionId') IS DISTINCT FROM (p_old->>'publishedVersionId') THEN
    v_caller := coalesce(
      auth.uid()::text,
      (SELECT k."createdBy"
         FROM util.request_api_key() r
         JOIN public."apiKey" k ON k.id = r.id AND k."companyId" = r.company_id
        WHERE r.company_id = p_new->>'companyId')
    );
    IF v_caller IS NULL OR (p_new->>'ownerId') IS DISTINCT FROM v_caller THEN
      RAISE EXCEPTION 'Only the owner of this workflow can publish it'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;

  IF p_operation = 'INSERT' THEN
    -- An API key has no auth.uid(); it acts for its creator (ctx.auditUserId).
    v_caller := coalesce(
      auth.uid()::text,
      (SELECT k."createdBy"
         FROM util.request_api_key() r
         JOIN public."apiKey" k ON k.id = r.id AND k."companyId" = r.company_id
        WHERE r.company_id = p_new->>'companyId')
    );
    IF v_caller IS NULL OR (p_new->>'ownerId') IS DISTINCT FROM v_caller THEN
      RAISE EXCEPTION 'A workflow can only be created with its creator as owner'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.check_workflow_version_lock(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- The published version runs as the workflow's owner, so an API role may only
  -- move its nodes (updateWorkflowNodePositions); mirrors checkWorkflowVersionLock.
  IF p_operation <> 'UPDATE'
     OR current_setting('role', true) IN ('anon', 'authenticated') IS NOT TRUE THEN
    RETURN;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public."workflow" w
     WHERE w.id = p_old->>'workflowId'
       AND w."companyId" = p_old->>'companyId'
       AND w."publishedVersionId" = p_old->>'id'
  ) THEN
    RETURN;
  END IF;

  IF (p_new - 'nodes' - 'updatedAt' - 'updatedBy') IS NOT DISTINCT FROM (p_old - 'nodes' - 'updatedAt' - 'updatedBy')
     AND jsonb_typeof(p_new->'nodes') = 'array'
     AND jsonb_typeof(p_old->'nodes') = 'array' THEN
    -- Same nodes in the same order once each node's position is set aside.
    IF jsonb_array_length(p_new->'nodes') = jsonb_array_length(p_old->'nodes')
       AND NOT EXISTS (
         SELECT 1
           FROM jsonb_array_elements(p_new->'nodes') WITH ORDINALITY AS n(node, i)
           JOIN jsonb_array_elements(p_old->'nodes') WITH ORDINALITY AS o(node, i) USING (i)
          WHERE (CASE WHEN jsonb_typeof(n.node) = 'object' THEN n.node - 'position' ELSE n.node END)
                IS DISTINCT FROM
                (CASE WHEN jsonb_typeof(o.node) = 'object' THEN o.node - 'position' ELSE o.node END)
       ) THEN
      RETURN;
    END IF;
  END IF;

  RAISE EXCEPTION 'This version is published. Create a new version to make changes.'
    USING ERRCODE = 'insufficient_privilege';
END;
$function$;

-- event triggers (packages/database/src/event-system/attachments.ts)
SET lock_timeout = '5s';
SELECT set_event_triggers('workflowVersion', ARRAY['check_workflow_version_lock']::text[], ARRAY[]::text[], false, ARRAY[]::text[]);
RESET lock_timeout;
